import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import styles from './Separator.module.css';

type SeparatorProps = HTMLArkProps<'span'> & {
  orientation?: 'horizontal' | 'vertical';
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'solid' | 'dashed' | 'dotted';
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
  'data-orientation'?: string;
  'data-size'?: string;
  'data-variant'?: string;
};

function Separator(props: SeparatorProps) {
  const [local, others] = splitProps(props, [
    'aria-orientation',
    'asChild',
    'class',
    'data-orientation',
    'data-part',
    'data-scope',
    'data-size',
    'data-slot',
    'data-variant',
    'orientation',
    'role',
    'size',
    'variant',
  ]);
  const orientation = () => local.orientation ?? 'horizontal';
  const role = () => local.role ?? 'separator';

  return (
    <ark.span
      asChild={local.asChild}
      {...others}
      role={role()}
      aria-orientation={role() === 'separator' ? orientation() : undefined}
      data-scope="separator"
      data-part="root"
      data-slot="separator-root"
      data-orientation={orientation()}
      data-size={local.size ?? 'sm'}
      data-variant={local.variant ?? 'solid'}
      class={clsx(styles.root, local.class)}
    />
  );
}

export { Separator };

@layer moduix.components {
  .root {
    display: block;
    flex-shrink: 0;
    margin: 0;
    border: 0;
    border-color: var(--moduix-separator-color, var(--moduix-color-border));
    border-style: var(
      --moduix-separator-border-style,
      var(--_separator-variant-border-style, solid)
    );

    &[data-size='xs'] {
      --_separator-size-thickness: var(--moduix-separator-thickness-xs, 0.5px);
    }

    &[data-size='sm'] {
      --_separator-size-thickness: var(
        --moduix-separator-thickness-sm,
        var(--moduix-border-width-sm)
      );
    }

    &[data-size='md'] {
      --_separator-size-thickness: var(
        --moduix-separator-thickness-md,
        var(--moduix-border-width-md)
      );
    }

    &[data-size='lg'] {
      --_separator-size-thickness: var(--moduix-separator-thickness-lg, 3px);
    }

    &[data-variant='dashed'] {
      --_separator-variant-border-style: dashed;
    }

    &[data-variant='dotted'] {
      --_separator-variant-border-style: dotted;
    }

    &[data-orientation='horizontal'] {
      width: var(--moduix-separator-length-horizontal, 100%);
      height: 0;
      border-block-start-width: var(
        --moduix-separator-thickness,
        var(--_separator-size-thickness, var(--moduix-border-width-sm))
      );
    }

    &[data-orientation='vertical'] {
      width: 0;
      height: var(--moduix-separator-length-vertical, 1em);
      border-inline-start-width: var(
        --moduix-separator-thickness,
        var(--_separator-size-thickness, var(--moduix-border-width-sm))
      );
    }
  }
}
